<script setup lang="ts">
import { computed,nextTick,onMounted,onUnmounted,ref } from 'vue'
import { ScanLine,Search,RotateCcw,RotateCw,Download,FileText,Trash2,X,ChevronLeft,ChevronRight,Grid2X2,List,ZoomIn,ZoomOut } from 'lucide-vue-next'
import PdfComposer from './PdfComposer.vue'
type Scan={id:string;name:string;mime:string;size:number;rotation:number;uploaded_at:number;width:number|null;height:number|null;thumb?:string}
const files=ref<Scan[]>([]),total=ref(0),selected=ref(new Set<string>()),active=ref(false),busy=ref(false),ended=ref(false),error=ref(''),notice=ref(''),search=ref(''),sort=ref('newest'),view=ref('grid'),page=ref(0),preview=ref<Scan|null>(null),previewUrl=ref(''),zoom=ref(1),fit=ref(true),pdfFiles=ref<Scan[]|null>(null),dialog=ref<HTMLDialogElement|null>(null)
let token='',anchor=0,timer:ReturnType<typeof setInterval>,heartbeatTimer:ReturnType<typeof setInterval>,refreshing=false
const cache=new Map<string,string>()
const allImages=computed(()=>selected.value.size>0&&[...selected.value].every(id=>files.value.find(f=>f.id===id)?.mime.startsWith('image/')))
const size=(n:number)=>n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(1)+' MB'
async function api(path:string,options:RequestInit={}){
 const response=await fetch(path,{...options,headers:{'X-Workspace-Token':token,...options.headers}})
 if(!response.ok){let message='操作失败';try{const data=await response.json();if(typeof data.detail==='string')message=data.detail}catch{}if(response.status===401){ended.value=true;clearInterval(timer);clearInterval(heartbeatTimer)}throw Error(message)}
 return response
}
async function post(path:string,payload:unknown={}){return api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)})}
async function refresh(){if(refreshing||ended.value)return;refreshing=true;try{
 const data=await(await api('/api/files?'+new URLSearchParams({q:search.value,sort:sort.value,offset:String(page.value*100),limit:'100'}))).json();if(ended.value)return;files.value=data.items;total.value=data.total;if(data.failed_files)error.value=`有 ${data.failed_files} 个文件未通过检查，请调整扫描格式后重扫。`
 const needed=new Set(files.value.filter(f=>f.mime!=='application/pdf').map(f=>f.id+':'+f.rotation))
 for(const [key,url] of cache){if(!needed.has(key)){URL.revokeObjectURL(url);cache.delete(key)}}
 for(const file of files.value){if(file.mime==='application/pdf')continue;const key=file.id+':'+file.rotation;if(!cache.has(key))try{cache.set(key,URL.createObjectURL(await(await api(`/api/files/${file.id}/thumbnail`)).blob()))}catch{}file.thumb=cache.get(key)}
 if(preview.value){const updated=files.value.find(f=>f.id===preview.value?.id);if(updated&&updated.rotation!==preview.value.rotation){preview.value=updated;await loadPreview(updated)}}
 }catch(e){error.value=(e as Error).message}finally{refreshing=false}}
async function start(){busy.value=true;error.value='';try{await post('/api/workspaces/start');active.value=true;notice.value='已领取扫描仪。请在扫描仪上选择 FTP，扫描后点击上传。'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function heartbeat(){try{const data=await(await post('/api/workspaces/heartbeat')).json();active.value=data.active}catch(e){error.value=(e as Error).message}}
function choose(file:Scan,index:number,event:MouseEvent){const next=new Set(selected.value);if(event.shiftKey){for(let i=Math.min(anchor,index);i<=Math.max(anchor,index);i++)next.add(files.value[i]!.id)}else if(event.ctrlKey||event.metaKey){next.has(file.id)?next.delete(file.id):next.add(file.id);anchor=index}else{next.clear();next.add(file.id);anchor=index}selected.value=next}
function toggle(id:string){const next=new Set(selected.value);next.has(id)?next.delete(id):next.add(id);selected.value=next}
function all(){selected.value=selected.value.size===files.value.length?new Set():new Set(files.value.map(f=>f.id))}
async function action(action:string,ids=[...selected.value]){if(action==='delete'&&!confirm('永久删除所选文件？没有回收站。'))return;busy.value=true;try{await post('/api/files/batch',{ids,action});if(action==='delete')selected.value=new Set();notice.value=action==='delete'?'所选文件已删除':'方向已更新，原件保持不变';await refresh()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function save(blob:Blob,name:string){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function download(file:Scan,rotated=false){try{save(await(await api(`/api/files/${file.id}/${rotated?'rotated':'original'}`)).blob(),rotated?file.name.replace(/\.[^.]+$/,'')+'-方向修正.png':file.name)}catch(e){error.value=(e as Error).message}}
async function zip(){const name=prompt('ZIP 文件名','本次扫描.zip');if(!name)return;busy.value=true;try{save(await(await post('/api/files/zip',{ids:[...selected.value],name})).blob(),name.endsWith('.zip')?name:name+'.zip')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function loadPreview(file:Scan){if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value=URL.createObjectURL(await(await api(`/api/files/${file.id}/preview`)).blob())}
async function openPreview(file:Scan){try{preview.value=file;zoom.value=1;fit.value=true;await loadPreview(file);await nextTick();dialog.value?.showModal()}catch(e){preview.value=null;error.value=(e as Error).message}}
function closePreview(){dialog.value?.close();preview.value=null;if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value=''}
function navigate(delta:number){const i=files.value.findIndex(f=>f.id===preview.value?.id);const next=files.value[i+delta];if(next)void openPreview(next)}
function releaseLocal(){for(const url of cache.values())URL.revokeObjectURL(url);cache.clear();closePreview();files.value=[];selected.value=new Set();total.value=0}
async function finish(){if(!confirm('确认已下载需要的文件？结束后本次数据将删除，无法恢复。'))return;busy.value=true;try{await post('/api/workspaces/end');ended.value=true;active.value=false;clearInterval(timer);clearInterval(heartbeatTimer);releaseLocal()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function pagehide(){if(token&&!ended.value){navigator.sendBeacon('/api/workspaces/end',new Blob([JSON.stringify({token})],{type:'application/json'}));ended.value=true;pdfFiles.value=null;releaseLocal();token='';document.documentElement.style.visibility='hidden'}}
function newWorkspace(){window.location.reload()}
function pageshow(e:PageTransitionEvent){if(e.persisted)location.reload()}
function keydown(e:KeyboardEvent){if((e.target as HTMLElement)?.matches('input,select,textarea'))return;if(preview.value){if(e.key==='ArrowLeft')navigate(-1);if(e.key==='ArrowRight')navigate(1)}else if((e.ctrlKey||e.metaKey)&&e.key==='a'){e.preventDefault();all()}}
onMounted(async()=>{window.addEventListener('pagehide',pagehide);window.addEventListener('pageshow',pageshow);window.addEventListener('keydown',keydown);try{const response=await fetch('/api/workspaces',{method:'POST'});if(!response.ok)throw Error('无法创建临时工作台');token=(await response.json()).token;await refresh();timer=setInterval(()=>void refresh(),2000);heartbeatTimer=setInterval(()=>void heartbeat(),20000)}catch(e){error.value=(e as Error).message}})
onUnmounted(()=>{pagehide();clearInterval(timer);clearInterval(heartbeatTimer);window.removeEventListener('pagehide',pagehide);window.removeEventListener('pageshow',pageshow);window.removeEventListener('keydown',keydown);releaseLocal()})
</script>
<template>
 <div class="workspace temporary">
  <header class="topbar"><div class="brand"><ScanLine :size="26"/>ScanHub<span>临时扫描工作台</span></div><span class="service"><i :class="{online:active}"></i>{{active?'扫描仪已由本页面领取':'尚未领取扫描仪'}}</span><button v-if="!ended" class="danger" :disabled="busy" @click="finish">结束并清理</button></header>
  <main>
   <div class="heading"><div><div class="eyebrow">扫描 · 整理 · 下载 · 结束</div><h1>本次扫描<span>{{total}}</span></h1><p>无需登录，仅本页面可见。请下载后结束；关闭页面后不恢复历史。</p></div><button v-if="!ended" class="primary" :disabled="active||busy" @click="start">{{active?'已领取扫描仪':'开始扫描'}}</button></div>
   <p v-if="error" class="banner error" role="alert">{{error}}<button aria-label="关闭错误" @click="error=''"><X :size="16"/></button></p><p v-if="notice&&!ended" class="banner success" role="status">{{notice}}</p>
   <div v-if="ended" class="empty"><ScanLine :size="40"/><h2>本次工作台已结束</h2><p>文件不再可访问。需要再次使用时，请打开新的工作台。</p><button class="primary" @click="newWorkspace">打开新工作台</button></div>
   <template v-else><div class="filters"><label class="search"><Search :size="17"/><input v-model="search" placeholder="搜索本次文件" aria-label="搜索本次文件" @input="page=0;refresh()"></label><label class="sort">排序<select v-model="sort" @change="refresh"><option value="newest">最新上传</option><option value="oldest">最早上传</option><option value="name">文件名称</option><option value="size">文件大小</option></select></label><div class="view-toggle"><button aria-label="网格视图" @click="view='grid'"><Grid2X2 :size="18"/></button><button aria-label="列表视图" @click="view='list'"><List :size="18"/></button></div></div>
  <div class="actionbar"><label class="select-all"><input type="checkbox" :checked="files.length>0&&selected.size===files.length" @change="all">本页全选</label><span class="selection-count">已选 {{selected.size}} 个</span><template v-if="selected.size"><button :disabled="busy" @click="zip"><Download :size="17"/>原件 ZIP</button><button :disabled="busy||!allImages" @click="pdfFiles=files.filter(f=>selected.has(f.id))"><FileText :size="17"/>合并 PDF</button><button :disabled="busy||!allImages" @click="action('left')"><RotateCcw :size="17"/>左旋 90°</button><button :disabled="busy||!allImages" @click="action('right')"><RotateCw :size="17"/>右旋 90°</button><button class="danger" :disabled="busy" @click="action('delete')"><Trash2 :size="17"/>删除</button></template></div>
  <div v-if="!files.length" class="empty"><ScanLine :size="46"/><h2>{{active?'等待扫描仪上传':'准备开始本次扫描'}}</h2><p>{{active?'在扫描仪选择 FTP，扫描完成后点击上传。':'先点击“开始扫描”，再操作扫描仪。其他人的文件不会出现在这里。'}}</p></div>
  <div v-else :class="['file-area',view]" style="--thumb:190px"><article v-for="(file,index) in files" :key="file.id" :class="['file',{selected:selected.has(file.id)}]" @click="choose(file,index,$event)" @dblclick="openPreview(file)"><div class="paper"><input type="checkbox" :aria-label="'选择 '+file.name" :checked="selected.has(file.id)" @click.stop @change="toggle(file.id)"><img v-if="file.thumb" :src="file.thumb" :alt="file.name" draggable="false"><FileText v-else :size="40"/><span v-if="file.rotation" class="rotation-badge">{{file.rotation}}°</span><button class="preview-button" @click.stop="openPreview(file)">预览</button></div><div class="file-meta"><button class="file-name" @click.stop="openPreview(file)">{{file.name}}</button><div class="meta-line"><span>{{new Date(file.uploaded_at*1000).toLocaleTimeString('zh-CN')}}</span><span>{{size(file.size)}}</span></div></div></article></div>
  <footer class="pagination"><span>没有历史记录和回收站 · 停止心跳 5 分钟后自动清理</span><div><button :disabled="!page" @click="page--;refresh()"><ChevronLeft :size="18"/></button><span>第 {{page+1}} 页</span><button :disabled="(page+1)*100>=total" @click="page++;refresh()"><ChevronRight :size="18"/></button></div></footer></template>
  </main>
  <PdfComposer v-if="pdfFiles" :files="pdfFiles" :token="token" @close="pdfFiles=null"/>
  <dialog ref="dialog" class="preview-dialog" @cancel.prevent="closePreview"><template v-if="preview"><header><strong>{{preview.name}}</strong><button aria-label="关闭预览" @click="closePreview"><X/></button></header><div class="preview-toolbar"><button aria-label="上一个文件" @click="navigate(-1)"><ChevronLeft/></button><button aria-label="下一个文件" @click="navigate(1)"><ChevronRight/></button><template v-if="preview.mime!=='application/pdf'"><button aria-label="缩小" @click="fit=false;zoom=Math.max(.25,zoom-.25)"><ZoomOut :size="18"/></button><button aria-label="放大" @click="fit=false;zoom=Math.min(4,zoom+.25)"><ZoomIn :size="18"/></button><button @click="fit=true">适应窗口</button><button @click="fit=false;zoom=1">100%</button><button @click="action('left',[preview.id])"><RotateCcw :size="17"/>左旋</button><button @click="action('right',[preview.id])"><RotateCw :size="17"/>右旋</button></template><button @click="download(preview)">下载原件</button><button v-if="['image/jpeg','image/png'].includes(preview.mime)" @click="download(preview,true)">下载方向修正 PNG</button></div><div class="preview-content"><iframe v-if="preview.mime==='application/pdf'" :src="previewUrl" title="PDF 预览" sandbox="allow-same-origin"></iframe><div v-else class="image-canvas"><img :src="previewUrl" :alt="preview.name" :class="{fit}" :style="fit?{}:{width:((preview.rotation%180?preview.height:preview.width)||1000)*zoom+'px',maxWidth:'none',maxHeight:'none'}"></div></div><p v-if="error" class="banner error">{{error}}</p></template></dialog>
 </div>
</template>
<style>.workspace.temporary{grid-template-columns:minmax(0,1fr)}.temporary .topbar .service{margin-left:auto}.temporary main{max-width:1600px;width:100%;margin:0 auto}.temporary .filters .search{margin:0;width:min(400px,100%)}@media(max-width:767px){.temporary .topbar{justify-content:space-between}.temporary .topbar .service{display:none}.temporary .heading{align-items:flex-start}.temporary .heading p{max-width:230px}.temporary .pagination{gap:8px;flex-wrap:wrap}}</style>
